import sys
import os

# Add both utils directories to path
utils_paths = [
    '/app/utils',
    '/app/modules/terraform-aws-ca-lambda/utils',
]

for path in utils_paths:
    if os.path.isdir(path) and path not in sys.path:
        sys.path.insert(0, path)

from lambda_code.tls_cert.tls_cert import (
    create_csr_info,
    create_csr_subject,
    CaChainResponse,
    CertificateResponse,
    Request,
)


def test_create_csr_info():
    event = {
        "common_name": "blah.example.com",
    }

    csr_info = create_csr_info(event)
    assert csr_info.purposes == ["client_auth"]
    assert csr_info.sans == ["blah.example.com"]


def test_create_csr_info_with_purpose_and_sans():
    event = {
        "common_name": "blah.example.com",
        "purposes": ["server_auth"],
        "sans": ["a.b.d.com"],
    }

    csr_info = create_csr_info(event)
    assert csr_info.purposes == ["server_auth"]
    assert csr_info.sans == ["a.b.d.com"]
